CREATE OR REPLACE FUNCTION public.confirm_edited_payment_image(_message uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE payer uuid; evidence_at timestamptz; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT c.payer_id,c.created_at INTO payer,evidence_at FROM public.payment_image_checks c JOIN public.messages m ON m.id=c.message_id WHERE c.message_id=_message AND m.sender_id=c.payer_id FOR UPDATE OF c; IF payer IS NULL THEN RAISE EXCEPTION 'EVIDENCE_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.payment_image_checks WHERE payer_id=payer AND message_id<>_message AND match_status='suspected_edit' AND created_at<evidence_at) THEN RAISE EXCEPTION 'PRIOR_WARNING_REQUIRED'; END IF; UPDATE public.membership_access SET revoked_at=now() WHERE request_id IN(SELECT id FROM public.membership_requests WHERE payer_id=payer); UPDATE public.membership_requests SET status='rejected',reviewed_at=now(),reviewed_by=auth.uid(),note='నిర్వాహకుడు మార్చిన చిత్రంగా నిర్ధారించారు' WHERE payer_id=payer AND status='pending'; PERFORM public.block_confirmed_content(payer,'హెచ్చరిక తర్వాత మళ్లీ మార్చిన చెల్లింపు చిత్రం: నిర్వాహకుడు నిర్ధారించారు'); END $$;
REVOKE ALL ON FUNCTION public.confirm_edited_payment_image(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_edited_payment_image(uuid) TO authenticated,service_role;